import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import DataTable from 'react-data-table-component'

class MyMessagesTable extends Component {


    handleChange = (event) => {
      
          this.props.handleMessagesSelectedRowsChange(event.selectedRows);
    }
    
    
    render() {
        
        const showMessagesTable = this.props.showMessagesTable ? {display: 'block'} : {display: 'none'};

        const columns =  [
            { name: 'Recipient', selector: 'profileName', sortable: true },
            { name: 'Profile URL', selector: 'profileUrl', sortable: true, hide: "sm" },
            { name: 'Messaged', selector: 'createdAt', sortable: true },
            { name: 'Message', selector: 'message', sortable: true }
            ];
               
        return (
          
          <Form className="messagesDataTable">
              <DataTable style={showMessagesTable}
                columns={columns}
                data={this.props.messageData}
                defaultSortField="profileName"
                selectableRows
                onSelectedRowsChange={this.handleChange}
                highlightOnHover
                clearSelectedRows={this.props.toggledClearRows}
                pagination
                paginationPerPage={10}
              />
                       
          </Form>
        )
    }

}

export default MyMessagesTable;
